import{_ as a,a0 as o,w as s,s as u,ao as r,I as l,x as t,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux有問必答：Linux 中如何安裝 7zip | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：Linux 中如何安裝 7zip | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：Linux 中如何安裝 7zip | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：Linux 中如何安裝 7zip | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141224 Linux FAQs with Answers--How to install 7zip on Linux","title":"Linux有問必答：Linux 中如何安裝 7zip","tag":"201501","desc":""},"relativePath":"201501/20141224 Linux FAQs with Answers--How to install 7zip on Linux.md","filePath":"[post].md"}'),z={name:"201501/20141224 Linux FAQs with Answers--How to install 7zip on Linux.md"};function d(x,i,f,m,L,g){const n=o("Link");return s(),u("div",null,[i[14]||(i[14]=r(`<h1 id="linux有問必答-linux-中如何安裝-7zip" tabindex="-1">Linux有問必答：Linux 中如何安裝 7zip <a class="header-anchor" href="#linux有問必答-linux-中如何安裝-7zip" aria-label="Permalink to “Linux有問必答：Linux 中如何安裝 7zip”">​</a></h1><blockquote><p><strong>問題</strong>: 我需要要從 ISO 映像中獲取某些文件，為此我想要使用 7zip 程序。那麼我應該如何安裝 7zip 軟件呢，[在 Linux 發佈版本上完全安裝]?</p></blockquote><p>7zip 是一款開源的歸檔應用程序，開始是為 Windows 系統而開發的。它能對多種格式的檔案文件進行打包或解包處理，除了支持其原生的 7z 格式的文檔外，還支持包括 XZ、GZIP、TAR、ZIP 和 BZIP2 等這些格式。 通常，7zip 也用來解壓 RAR、DEB、RPM 和 ISO 等格式的文件。除了簡單的歸檔功能，7zip 還具有支持 AES-256 算法加密以及自解壓和建立多卷存檔功能。在支持 POSIX 標準的系統上（Linux、Unix、BSD），原生的 7zip 程序被移植過來並被命名為 p7zip（“POSIX 7zip” 的簡稱）。</p><p>下面介紹如何在 Linux 中安裝 7zip （或 p7zip）。</p><h3 id="在-debian、ubuntu-或-linux-mint-系統中安裝-7zip" tabindex="-1">在 Debian、Ubuntu 或 Linux Mint 系統中安裝 7zip <a class="header-anchor" href="#在-debian、ubuntu-或-linux-mint-系統中安裝-7zip" aria-label="Permalink to “在 Debian、Ubuntu 或 Linux Mint 系統中安裝 7zip”">​</a></h3><p>在基於的 Debian 的發佈系統中存在有三種 7zip 的軟件包。</p><ul><li><strong>p7zip</strong>: 包含 7zr（最小的 7zip 歸檔工具），僅僅只能處理原生的 7z 格式。</li><li><strong>p7zip-full</strong>: 包含 7z ，支持 7z、LZMA2、XZ、ZIP、CAB、GZIP、BZIP2、ARJ、TAR、CPIO、RPM、ISO 和 DEB 格式。</li><li><strong>p7zip-rar</strong>: 包含一個能解壓 RAR 文件的插件。</li></ul><p>建議安裝 p7zip-full 包（不是 p7zip），因為這是最完全的 7zip 程序包，它支持很多歸檔格式。此外，如果您想處理 RAR 文件話，還需要安裝 p7zip-rar 包，做成一個獨立的插件包的原因是因為 RAR 是一種專有格式。</p><pre><code>$ sudo apt-get install p7zip-full p7zip-rar 
</code></pre><h3 id="在-fedora-或-centos-rhel-系統中安裝-7zip" tabindex="-1">在 Fedora 或 CentOS/RHEL 系統中安裝 7zip <a class="header-anchor" href="#在-fedora-或-centos-rhel-系統中安裝-7zip" aria-label="Permalink to “在 Fedora 或 CentOS/RHEL 系統中安裝 7zip”">​</a></h3><p>基於紅帽的發佈系統上提供了兩個 7zip 的軟件包。</p><ul><li><strong>p7zip</strong>: 包含 7za 命令，支持 7z、ZIP、GZIP、CAB、ARJ、BZIP2、TAR、CPIO、RPM 和 DEB 格式。</li><li><strong>p7zip-plugins</strong>: 包含 7z 命令，額外的插件，它擴展了 7za 命令（例如支持 ISO 格式的抽取）。</li></ul>`,12)),l("p",null,[i[1]||(i[1]=t("在 CentOS/RHEL 系統中，在運行下面命令前您需要確保 ",-1)),e(n,{href:"http://linux.cn/article-2324-1.html"},{default:p(()=>[...i[0]||(i[0]=[t("EPEL 資源庫",-1)])]),_:1}),i[2]||(i[2]=t(" 可用，但在 Fedora 系統中就不需要額外的資源庫了。",-1))]),i[15]||(i[15]=r(`<pre><code>$ sudo yum install p7zip p7zip-plugins 
</code></pre><p>注意，跟基於 Debian 的發佈系統不同的是，基於紅帽的發佈系統沒有提供 RAR 插件，所以您不能使用 7z 命令來抽取解壓 RAR 文件。</p><h3 id="使用-7z-創建或提取歸檔文件" tabindex="-1">使用 7z 創建或提取歸檔文件 <a class="header-anchor" href="#使用-7z-創建或提取歸檔文件" aria-label="Permalink to “使用 7z 創建或提取歸檔文件”">​</a></h3><p>一旦安裝好 7zip 軟件後，就可以使用 7z 命令來打包解包各式各樣的歸檔文件了。7z 命令會使用不同的插件來輔助處理對應格式的歸檔文件。</p><p><img src="https://farm8.staticflickr.com/7583/15874000610_878a85b06a_b.jpg" alt=""></p><p>使用 “a” 選項就可以創建一個歸檔文件，它可以創建 7z、XZ、GZIP、TAR、 ZIP 和 BZIP2 這幾種格式的文件。如果指定的歸檔文件已經存在的話，它會把文件“附加”到存在的歸檔中，而不是覆蓋原有歸檔文件。</p><pre><code>$ 7z a &lt;archive-filename&gt; &lt;list-of-files&gt; 
</code></pre><p>使用 “e” 選項可以抽取一個歸檔文件，抽取出的文件會放在當前目錄。抽取支持的格式比創建時支持的格式要多的多，包括 7z、XZ、GZIP、TAR、ZIP、BZIP2、LZMA2、CAB、ARJ、CPIO、RPM、ISO 和 DEB 這些格式。</p><pre><code>$ 7z e &lt;archive-filename&gt;
</code></pre><p>解包的另外一種方式是使用 “x” 選項。和 “e” 選項不同的是，它使用的是全路徑來抽取歸檔的內容。</p><pre><code>$ 7z x &lt;archive-filename&gt;
</code></pre><p>要查看歸檔的文件列表，使用 “l” 選項。</p><pre><code>$ 7z l &lt;archive-filename&gt;
</code></pre><p>要更新或刪除歸檔文件，分別使用 “u” 和 “d” 選項。</p><pre><code>$ 7z u &lt;archive-filename&gt; &lt;list-of-files-to-update&gt;
$ 7z d &lt;archive-filename&gt; &lt;list-of-files-to-delete&gt;
</code></pre><p>要測試歸檔的完整性，使用：</p><pre><code>$ 7z t &lt;archive-filename&gt; 
</code></pre><hr>`,18)),l("p",null,[i[4]||(i[4]=t("via:",-1)),e(n,{href:"http://ask.xmodulo.com/install-7zip-linux.html"},{default:p(()=>[...i[3]||(i[3]=[t("http://ask.xmodulo.com/install-7zip-linux.html",-1)])]),_:1})]),l("p",null,[i[7]||(i[7]=t("譯者：",-1)),e(n,{href:"https://github.com/runningwater"},{default:p(()=>[...i[5]||(i[5]=[t("runningwater",-1)])]),_:1}),i[8]||(i[8]=t(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...i[6]||(i[6]=[t("wxy",-1)])]),_:1})]),l("p",null,[i[11]||(i[11]=t("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...i[9]||(i[9]=[t("LCTT",-1)])]),_:1}),i[12]||(i[12]=t(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:p(()=>[...i[10]||(i[10]=[t("Linux中國",-1)])]),_:1}),i[13]||(i[13]=t(" 榮譽推出",-1))])])}const I=a(z,[["render",d]]);export{T as __pageData,I as default};
